  "implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be a dict')
    if 'threshold' not in case or 'calls' not in case:
        raise ValueError('case must contain threshold and calls')
    threshold = case['threshold']
    calls = case['calls']
    if not isinstance(calls, list):
        raise ValueError('calls must be a list')
    diagnostics = []
    accepted_ids = []
    for call in calls:
        if not isinstance(call, dict):
            raise ValueError('each call must be a dict')
        required = ('call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable')
        if any(k not in call for k in required):
            raise ValueError('call missing required fields')
        call_id = call['call_id']
        gain = call['loss_without_call'] - call['loss_with_call']
        tokens = call['prediction_tokens']
        if tokens <= 0:
            raise ValueError('prediction_tokens must be positive')
        norm_gain = gain / tokens
        parseable = call['parseable']
        accepted = bool(parseable) and norm_gain >= threshold
        if accepted:
            accepted_ids.append(call_id)
        diagnostics.append({'call_id': call_id, 'accepted': accepted, 'normalized_gain': round(norm_gain, 8)})
    return {'accepted_call_ids': accepted_ids, 'diagnostics': diagnostics}"
}
